1	package common
2	import chisel3._
3	import chisel3.util._
4	
5	class ForceZero[T <: Data](gen: T) extends Module {
6	  val io = IO(new Bundle {
7	    val in = Input(Valid(gen))
8	    val out = Output(gen)
9	  })
10	  io.out := Mux(io.in.valid, io.in.bits, 0.U.asTypeOf(gen))
11	}
12	
13	// Zip32: interleave two sz-word values
14	// sz=4 (word), sz=2 (half), sz=1 (byte)
15	object Zip32 {
16	  def apply(sz: Int, a: UInt, b: UInt): UInt = {
17	    val result = Wire(UInt(64.W))
18	    val chunks = 32 / (sz * 8)
19	    val chunkBits = sz * 8
20	    val parts = (0 until chunks).map { i =>
21	      Cat(b(i*chunkBits + chunkBits-1, i*chunkBits), a(i*chunkBits + chunkBits-1, i*chunkBits))
22	    }
23	    result := parts.foldRight(0.U(64.W))((a, b) => Cat(a, b))
24	    result
25	  }
26	}
27	
28	class RotateVectorLeft[T <: Data](gen: T, n: Int) extends Module {
29	  val io = IO(new Bundle {
30	    val in = Input(Vec(n, gen))
31	    val shift = Input(UInt(log2Ceil(n).W))
32	    val out = Output(Vec(n, gen))
33	  })
34	  for (i <- 0 until n) {
35	    io.out(i) := io.in((i.U + io.shift) % n.U)
36	  }
37	}
38	
39	class RotateVectorRight[T <: Data](gen: T, n: Int) extends Module {
40	  val io = IO(new Bundle {
41	    val in = Input(Vec(n, gen))
42	    val shift = Input(UInt(log2Ceil(n).W))
43	    val out = Output(Vec(n, gen))
44	  })
45	  for (i <- 0 until n) {
46	    io.out(i) := io.in((i.U + n.U - io.shift) % n.U)
47	  }
48	}
49	
50	class ShiftVectorLeft[T <: Data](gen: T, n: Int) extends Module {
51	  val io = IO(new Bundle {
52	    val in = Input(Vec(n, gen))
53	    val shift = Input(UInt(log2Ceil(n+1).W))
54	    val out = Output(Vec(n, gen))
55	  })
56	  for (i <- 0 until n) {
57	    val idx = i.U + io.shift
58	    io.out(i) := Mux(idx < n.U, io.in(idx), 0.U.asTypeOf(gen))
59	  }
60	}
61	
62	class ShiftVectorRight[T <: Data](gen: T, n: Int) extends Module {
63	  val io = IO(new Bundle {
64	    val in = Input(Vec(n, gen))
65	    val shift = Input(UInt(log2Ceil(n+1).W))
66	    val out = Output(Vec(n, gen))
67	  })
68	  for (i <- 0 until n) {
69	    io.out(i) := Mux(io.shift <= i.U, io.in(i.U - io.shift), 0.U.asTypeOf(gen))
70	  }
71	}
