// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

package coralnpu

import chisel3._
import chisel3.util._

object MluOp extends ChiselEnum {
  val MUL, MULH, MULHSU, MULHU, MAC = Value
}

// 4-slot multiply unit.  Accepts one of 4 dispatch slots, produces one result.
// Latency: 1 cycle (result registered, consumed via Decoupled handshake).
class Mlu(p: Parameters) extends Module {
  val io = IO(new Bundle {
    val req = Vec(4, Flipped(Valid(new Bundle {
      val addr = UInt(5.W)
      val op   = MluOp()
    })))
    val rs1 = Vec(4, Input(new Bundle {
      val valid = Bool()
      val data  = UInt(32.W)
    }))
    val rs2 = Vec(4, Input(new Bundle {
      val valid = Bool()
      val data  = UInt(32.W)
    }))
    val rd = Decoupled(new Bundle {
      val addr = UInt(5.W)
      val data = UInt(32.W)
    })
  })

  // Pick the first valid slot (priority encoder)
  val selValid = io.req.map(_.valid).reduce(_ || _)
  val selIdx   = PriorityEncoder(VecInit(io.req.map(_.valid)))

  val selReq = io.req(selIdx)
  val selRs1 = io.rs1(selIdx).data
  val selRs2 = io.rs2(selIdx).data
  val selOp  = selReq.bits.op
  val selAddr = selReq.bits.addr

  // ── Combinational multiply ────────────────────────────────────────────────
  val product64s  = (selRs1.asSInt * selRs2.asSInt).asUInt  // signed × signed
  val product64u  = selRs1 * selRs2                          // unsigned × unsigned
  val product64su = (selRs1.asSInt * selRs2).asUInt          // signed × unsigned

  val mulResult = Wire(UInt(32.W))
  mulResult := 0.U
  switch (selOp) {
    is (MluOp.MUL)    { mulResult := product64s(31,0)  }
    is (MluOp.MULH)   { mulResult := product64s(63,32) }
    is (MluOp.MULHU)  { mulResult := product64u(63,32) }
    is (MluOp.MULHSU) { mulResult := product64su(63,32) }
    is (MluOp.MAC)    { mulResult := product64s(31,0)  }
  }

  // ── Registered output (1-cycle latency) with Decoupled back-pressure ─────
  val resultValid = RegInit(false.B)
  val resultAddr  = RegInit(0.U(5.W))
  val resultData  = RegInit(0.U(32.W))

  // Capture when a valid request comes in and output register is empty/consumed
  val capture = selValid && (!resultValid || io.rd.fire)

  when (io.rd.fire && !selValid) {
    resultValid := false.B
  } .elsewhen (capture) {
    resultValid := true.B
    resultAddr  := selAddr
    resultData  := mulResult
  }

  io.rd.valid      := resultValid
  io.rd.bits.addr  := resultAddr
  io.rd.bits.data  := resultData
}

// Copyright 2025 Google LLC
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
//     http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

package coralnpu

import chisel3._
import chisel3.util._

import common.{IDiv, IDivReq}

object DvuOp extends ChiselEnum {
  val DIV, DIVU, REM, REMU = Value
}

// Divide unit – wraps the common IDiv iterative divider.
class Dvu(p: Parameters) extends Module {
  val io = IO(new Bundle {
    val req = Flipped(Valid(new Bundle {
      val addr = UInt(5.W)
      val op   = DvuOp()
    }))
    val rs1 = Input(new Bundle {
      val valid = Bool()
      val data  = UInt(32.W)
    })
    val rs2 = Input(new Bundle {
      val valid = Bool()
      val data  = UInt(32.W)
    })
    val rd = Decoupled(new Bundle {
      val addr = UInt(5.W)
      val data = UInt(32.W)
    })
  })

  val div = Module(new IDiv)

  // Track in-flight request metadata
  val inflight     = RegInit(false.B)
  val inflightAddr = RegInit(0.U(5.W))

  val isSigned = (io.req.bits.op === DvuOp.DIV) || (io.req.bits.op === DvuOp.REM)
  val isRem    = (io.req.bits.op === DvuOp.REM) || (io.req.bits.op === DvuOp.REMU)
  val canAccept = !inflight || div.io.resp.fire

  // Feed IDiv
  div.io.req.valid          := io.req.valid && canAccept
  div.io.req.bits.dividend  := io.rs1.data
  div.io.req.bits.divisor   := io.rs2.data
  div.io.req.bits.signed_   := isSigned
  div.io.req.bits.rem       := isRem

  when (div.io.req.fire) {
    inflight     := true.B
    inflightAddr := io.req.bits.addr
  } .elsewhen (div.io.resp.fire) {
    inflight := false.B
  }

  // Collect result
  div.io.resp.ready    := io.rd.ready
  io.rd.valid          := div.io.resp.valid
  io.rd.bits.data      := div.io.resp.bits.result
  io.rd.bits.addr      := inflightAddr
}

// Copyright 2025 Google LLC
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
//     http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

package coralnpu

import chisel3._
import chisel3.util._

// Integer register file with scoreboard support.
// nReadPorts  – number of concurrent read ports
// nWritePorts – number of concurrent write ports (higher index wins on conflict)
class Regfile(p: Parameters, nReadPorts: Int = 4, nWritePorts: Int = 6) extends Module {
  val io = IO(new Bundle {
    val scoreboard     = Output(UInt(32.W))
    val scoreboard_set = Input(UInt(32.W))
    val read_ports     = Vec(nReadPorts,  new RegfileReadPort)
    val write_ports    = Vec(nWritePorts, new RegfileWritePort)
  })

  // 32 × 32-bit register file; x0 is hardwired to zero
  val regs = RegInit(VecInit(Seq.fill(32)(0.U(32.W))))

  // Scoreboard: bitmask of registers with outstanding (in-flight) writes
  val scoreboard = RegInit(0.U(32.W))
  io.scoreboard := scoreboard

  // ── Write ports (higher index wins on same-address conflict) ─────────────
  for (wp <- 0 until nWritePorts) {
    when (io.write_ports(wp).valid && io.write_ports(wp).addr =/= 0.U) {
      regs(io.write_ports(wp).addr) := io.write_ports(wp).data
    }
  }

  // Update scoreboard: set bits from scoreboard_set, then clear bits for
  // all registers written this cycle.
  val clearMask = io.write_ports.foldLeft(0.U(32.W)) { (acc, wp) =>
    Mux(wp.valid && wp.addr =/= 0.U,
        acc | (1.U(32.W) << wp.addr),
        acc)
  }
  scoreboard := (scoreboard | io.scoreboard_set) & ~clearMask

  // ── Read ports ────────────────────────────────────────────────────────────
  for (rp <- 0 until nReadPorts) {
    // Forward from the highest-priority writer that matches this address
    // (bypassing writes happening in the same cycle)
    val bypass = Wire(Valid(UInt(32.W)))
    bypass.valid := false.B
    bypass.bits  := 0.U

    for (wp <- 0 until nWritePorts) {
      when (io.write_ports(wp).valid &&
            io.write_ports(wp).addr === io.read_ports(rp).addr &&
            io.read_ports(rp).addr =/= 0.U) {
        bypass.valid := true.B
        bypass.bits  := io.write_ports(wp).data
      }
    }

    io.read_ports(rp).data :=
      Mux(io.read_ports(rp).addr === 0.U, 0.U,
        Mux(bypass.valid, bypass.bits,
          regs(io.read_ports(rp).addr)))
  }
}

// Copyright 2025 Google LLC
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
//     http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

package coralnpu

import chisel3._
import chisel3.util._

object BruOp extends ChiselEnum {
  val BEQ, BNE, BLT, BGE, BLTU, BGEU, JAL, JALR = Value
}

// Branch/jump unit – purely combinational (single-cycle).
class Bru(p: Parameters) extends Module {
  val io = IO(new Bundle {
    val req = Flipped(Valid(new Bundle {
      val op     = BruOp()
      val pc     = UInt(32.W)
      val imm    = SInt(32.W)
      val rs1    = UInt(32.W)
      val rs2    = UInt(32.W)
      val rdAddr = UInt(5.W)
    }))
    // Branch target (valid when branch/jump taken)
    val branch = Valid(UInt(32.W))
    // Link register result (JAL / JALR write pc+4 to rd)
    val rd = Valid(new Bundle {
      val addr = UInt(5.W)
      val data = UInt(32.W)
    })
  })

  val op  = io.req.bits.op
  val pc  = io.req.bits.pc
  val imm = io.req.bits.imm
  val rs1 = io.req.bits.rs1
  val rs2 = io.req.bits.rs2

  // Branch condition evaluation
  val taken = Wire(Bool())
  taken := false.B
  switch (op) {
    is (BruOp.BEQ)  { taken := (rs1 === rs2) }
    is (BruOp.BNE)  { taken := (rs1 =/= rs2) }
    is (BruOp.BLT)  { taken := (rs1.asSInt < rs2.asSInt) }
    is (BruOp.BGE)  { taken := (rs1.asSInt >= rs2.asSInt) }
    is (BruOp.BLTU) { taken := (rs1 < rs2) }
    is (BruOp.BGEU) { taken := (rs1 >= rs2) }
    is (BruOp.JAL)  { taken := true.B }
    is (BruOp.JALR) { taken := true.B }
  }

  // Target address
  val target = Wire(UInt(32.W))
  target := 0.U
  switch (op) {
    is (BruOp.JALR) {
      // JALR: target = (rs1 + imm) & ~1
      target := (rs1.asSInt + imm).asUInt & ~1.U(32.W)
    }
    is (BruOp.JAL, BruOp.BEQ, BruOp.BNE, BruOp.BLT, BruOp.BGE, BruOp.BLTU, BruOp.BGEU) {
      target := (pc.asSInt + imm).asUInt
    }
  }

  val isJump = (op === BruOp.JAL) || (op === BruOp.JALR)

  io.branch.valid := io.req.valid && taken
  io.branch.bits  := target

  // JAL / JALR write pc+4 back to rd
  io.rd.valid      := io.req.valid && isJump
  io.rd.bits.addr  := io.req.bits.rdAddr
  io.rd.bits.data  := pc + 4.U
}

