package coralnpu

import chisel3._
import chisel3.util._

object LsuOp extends ChiselEnum {
  val LOAD, STORE, LOAD_FLOAT, STORE_FLOAT = Value
}

// Load/Store Unit.
// Converts CPU load/store requests into DBus transactions.
// Supports narrow (32-bit) and wide (128-bit) data bus widths.
class Lsu(p: Parameters) extends Module {
  val dataBits  = p.lsuDataBits
  val dataBytes = dataBits / 8

  val io = IO(new Bundle {
    val req = Flipped(Valid(new Bundle {
      val addr    = UInt(32.W)
      val rdAddr  = UInt(5.W)
      val op      = LsuOp()
      val wdata   = UInt(32.W)
      val size    = UInt(2.W)   // 0=byte, 1=half, 2=word
      val signExt = Bool()
    }))
    val dbus  = new DBusBundle(dataBits)
    val rd    = Valid(new Bundle {
      val addr = UInt(5.W)
      val data = UInt(32.W)
    })
    val busy  = Output(Bool())
  })

  // ── State ──────────────────────────────────────────────────────────────────
  object State extends ChiselEnum {
    val IDLE, WAIT = Value
  }
  val state   = RegInit(State.IDLE)
  val reqReg  = RegInit(0.U.asTypeOf(io.req.bits))
  val busy    = RegInit(false.B)

  io.busy := busy

  // ── Address alignment for wide bus ─────────────────────────────────────────
  // For a 128-bit bus the word address is addr[31:4]; byte offset is addr[3:0].
  val byteOffset = io.req.bits.addr(log2Ceil(dataBytes)-1, 0)

  // ── Write data / mask generation ───────────────────────────────────────────
  def genWdata(wdata32: UInt, byteOff: UInt, size: UInt): UInt = {
    if (dataBits == 32) {
      val shifted = Wire(UInt(32.W))
      shifted := MuxCase(wdata32, Seq(
        (size === 0.U) -> Cat(wdata32(7,0), wdata32(7,0), wdata32(7,0), wdata32(7,0)),
        (size === 1.U) -> Cat(wdata32(15,0), wdata32(15,0))
      ))
      shifted
    } else {
      // 128-bit: replicate 32-bit word and shift by byte offset
      val rep = Cat(wdata32, wdata32, wdata32, wdata32)  // 128-bit
      rep
    }
  }

  def genWmask(byteOff: UInt, size: UInt): UInt = {
    val byteMask1 = "b0001".U(4.W)
    val byteMask2 = "b0011".U(4.W)
    val byteMask4 = "b1111".U(4.W)
    val narrowMask = MuxCase(byteMask4, Seq(
      (size === 0.U) -> byteMask1,
      (size === 1.U) -> byteMask2
    ))
    if (dataBits == 32) {
      narrowMask
    } else {
      // Shift narrowMask left by byte offset within the wide word
      (narrowMask << byteOff)(dataBytes-1, 0)
    }
  }

  // ── DBus signals ───────────────────────────────────────────────────────────
  val isLoad  = (io.req.bits.op === LsuOp.LOAD)  || (io.req.bits.op === LsuOp.LOAD_FLOAT)
  val isStore = (io.req.bits.op === LsuOp.STORE) || (io.req.bits.op === LsuOp.STORE_FLOAT)

  // Bus address: aligned to bus word boundary
  val busAddr = if (dataBits == 32) {
    io.req.bits.addr
  } else {
    Cat(io.req.bits.addr(31, log2Ceil(dataBytes)), 0.U(log2Ceil(dataBytes).W))
  }

  io.dbus.valid := state === State.IDLE && io.req.valid
  io.dbus.addr  := Mux(state === State.IDLE, busAddr, Cat(reqReg.addr(31, log2Ceil(dataBytes)), 0.U(log2Ceil(dataBytes).W)))
  io.dbus.write := isStore
  io.dbus.wdata := genWdata(io.req.bits.wdata, byteOffset, io.req.bits.size)
  io.dbus.wmask := genWmask(byteOffset, io.req.bits.size)
  io.dbus.size  := io.req.bits.size

  // ── FSM ────────────────────────────────────────────────────────────────────
  when (state === State.IDLE && io.req.valid) {
    when (!io.dbus.ready) {
      // Bus stalled: move to WAIT with a latched copy
      state   := State.WAIT
      reqReg  := io.req.bits
      busy    := true.B
    } .otherwise {
      busy := isLoad  // stays busy until read data returns (simple 1-cycle bus model)
    }
  }

  when (state === State.WAIT) {
    io.dbus.valid := true.B
    io.dbus.addr  := Cat(reqReg.addr(31, log2Ceil(dataBytes)), 0.U(log2Ceil(dataBytes).W))
    io.dbus.write := (reqReg.op === LsuOp.STORE) || (reqReg.op === LsuOp.STORE_FLOAT)
    io.dbus.wdata := genWdata(reqReg.wdata, reqReg.addr(log2Ceil(dataBytes)-1, 0), reqReg.size)
    io.dbus.wmask := genWmask(reqReg.addr(log2Ceil(dataBytes)-1, 0), reqReg.size)
    io.dbus.size  := reqReg.size
    when (io.dbus.ready) {
      state := State.IDLE
      busy  := false.B
    }
  }

  // ── Read data extraction ───────────────────────────────────────────────────
  // Latch the request that was accepted so we can use it on the return cycle
  val pendingReg    = RegInit(false.B)
  val pendingMeta   = RegInit(0.U.asTypeOf(io.req.bits))

  when (io.dbus.valid && io.dbus.ready && !io.dbus.write) {
    pendingReg  := true.B
    pendingMeta := Mux(state === State.WAIT, reqReg, io.req.bits)
  } .elsewhen (pendingReg) {
    pendingReg := false.B
  }

  // Extract the correct sub-word from the bus return data
  val rdataRaw = io.dbus.rdata
  val byteOffPending = pendingMeta.addr(log2Ceil(dataBytes)-1, 0)
  val rdataShifted   = if (dataBits == 32) rdataRaw else
    (rdataRaw >> (byteOffPending << 3))(31, 0)

  val rdataByte = Cat(Fill(24, Mux(pendingMeta.signExt, rdataShifted(7),  0.U(1.W))), rdataShifted(7,0))
  val rdataHalf = Cat(Fill(16, Mux(pendingMeta.signExt, rdataShifted(15), 0.U(1.W))), rdataShifted(15,0))
  val rdataWord = rdataShifted(31,0)

  val rdataFinal = MuxCase(rdataWord, Seq(
    (pendingMeta.size === 0.U) -> rdataByte,
    (pendingMeta.size === 1.U) -> rdataHalf
  ))

  io.rd.valid      := pendingReg
  io.rd.bits.addr  := pendingMeta.rdAddr
  io.rd.bits.data  := rdataFinal
}

