package coralnpu

import chisel3._
import chisel3.util._

// ── Fetcher ────────────────────────────────────────────────────────────────
// Converts a fetch-address request into an IBus transaction and
// reassembles the individual 32-bit instructions from the wide rdata word.
class Fetcher(p: Parameters) extends Module {
  val nInst = p.fetchDataBits / 32

  val io = IO(new Bundle {
    val ctrl  = Flipped(Valid(UInt(32.W)))
    val ibus  = new IBusBundle(p.fetchDataBits)
    val fetch = Valid(new Bundle {
      val addr = UInt(32.W)
      val inst = Vec(nInst, UInt(32.W))
    })
  })

  // Latch the pending request address
  val pendingValid = RegInit(false.B)
  val pendingAddr  = RegInit(0.U(32.W))

  // Accept a new request when we are idle
  val accept = io.ctrl.valid && (!pendingValid || (io.ibus.valid && io.ibus.ready))

  when (accept) {
    pendingValid := true.B
    pendingAddr  := io.ctrl.bits
  } .elsewhen (io.ibus.valid && io.ibus.ready) {
    pendingValid := false.B
  }

  // Drive IBus
  io.ibus.valid := pendingValid
  io.ibus.addr  := pendingAddr

  // Capture result when bus responds
  val resultValid = RegInit(false.B)
  val resultAddr  = RegInit(0.U(32.W))
  val resultData  = RegInit(0.U(p.fetchDataBits.W))

  when (io.ibus.valid && io.ibus.ready) {
    resultValid := true.B
    resultAddr  := pendingAddr
    resultData  := io.ibus.rdata
  } .otherwise {
    resultValid := false.B
  }

  io.fetch.valid      := resultValid
  io.fetch.bits.addr  := resultAddr
  for (i <- 0 until nInst) {
    io.fetch.bits.inst(i) := resultData(i*32+31, i*32)
  }
}

// ── FetchControl ───────────────────────────────────────────────────────────
// Manages the fetch address stream.  Handles:
//  - Reset → boot from csr.value(0)
//  - Sequential fetch: advance PC by (nInst * 4) each cycle
//  - Branch: redirect to branch target
//  - Backpressure: stall when instruction buffer is too full
//  - JAL detection: truncate fetch group at unconditional branch
class FetchControl(p: Parameters) extends Module {
  val nInst = p.fetchDataBits / 32

  val io = IO(new Bundle {
    val fetchAddr   = Decoupled(UInt(32.W))
    val fetchData   = Flipped(Valid(new Bundle {
      val addr = UInt(32.W)
      val inst = Vec(nInst, UInt(32.W))
    }))
    val bufferRequest = new Bundle {
      val nValid = Output(UInt(4.W))
      val nReady = Input(UInt(4.W))
    }
    val bufferSpaces = Input(UInt(4.W))
    val csr          = new CsrReadPort
    val branch       = Flipped(Valid(UInt(32.W)))
  })

  // ── PC register ────────────────────────────────────────────────────────────
  val bootAddr = io.csr.value(0)

  // After reset, start from boot address
  val pc       = RegInit(0.U(32.W))
  val started  = RegInit(false.B)

  when (!started) {
    pc      := bootAddr
    started := true.B
  }

  // ── Branch redirect ─────────────────────────────────────────────────────────
  val branching     = RegInit(false.B)
  val branchTarget  = RegInit(0.U(32.W))

  when (io.branch.valid) {
    branching    := true.B
    branchTarget := io.branch.bits
  }

  // ── Scan fetched group for unconditional branches ──────────────────────────
  // JAL zero,0 = 0x0000006f → unconditional JAL; detect JAL opcode = 0x6f
  def isJalInst(inst: UInt): Bool = inst(6,0) === "b1101111".U

  // Find index of first JAL (or return nInst if none found)
  val jalIdx = Wire(UInt(4.W))
  jalIdx := nInst.U
  for (i <- (nInst-1) to 0 by -1) {
    when (isJalInst(io.fetchData.bits.inst(i))) {
      jalIdx := i.U
    }
  }
  val hasJal  = jalIdx < nInst.U
  val nFetch  = Mux(hasJal, jalIdx + 1.U, nInst.U)

  // ── Backpressure: only fetch if buffer has room for a full group ────────────
  val canFetch = io.bufferSpaces >= nInst.U

  // ── fetchAddr: request a new cache line ─────────────────────────────────────
  val fetchPending = RegInit(false.B)
  val fetchPC      = RegInit(0.U(32.W))

  // Compute next PC after current fetch word
  val fetchWordBytes = (nInst * 4).U(32.W)

  // ── Buffer request output ──────────────────────────────────────────────────
  // nValid = number of instructions to push this cycle (only when fetch data valid
  // and we are NOT branching and the data is for the current expected address)
  val pushNow = io.fetchData.valid && !io.branch.valid

  io.bufferRequest.nValid := Mux(
    pushNow,
    Mux(io.bufferRequest.nReady < nFetch, io.bufferRequest.nReady, nFetch)(3,0),
    0.U(4.W)
  )

  // ── fetchAddr handshake ─────────────────────────────────────────────────────
  // Send a fetch request when:
  //  (a) We are started and not branching, and buffer has space
  //  (b) A branch just resolved
  val resolvedBranch = branching && !io.branch.valid

  val nextFetchAddr = Wire(UInt(32.W))
  nextFetchAddr := 0.U
  when (resolvedBranch) {
    nextFetchAddr := branchTarget
  } .elsewhen (io.fetchData.valid && !io.branch.valid) {
    // After receiving fetch data, advance PC
    nextFetchAddr := io.fetchData.bits.addr + (nFetch << 2.U)(31,0)
  } .otherwise {
    nextFetchAddr := pc
  }

  // Update PC
  when (resolvedBranch) {
    pc       := branchTarget
    branching := false.B
  } .elsewhen (io.fetchData.valid && !io.branch.valid) {
    pc := io.fetchData.bits.addr + (nFetch << 2.U)(31,0)
  }

  // fetchAddr.valid: drive a fetch when:
  //  - started
  //  - buffer has room (canFetch) OR we just resolved a branch
  //  - not currently branching (waiting for redirect)
  val sendFetch = started && canFetch && !branching && !io.branch.valid

  io.fetchAddr.valid := sendFetch
  io.fetchAddr.bits  := nextFetchAddr
}

