// CTZ: count trailing zeros – reverse then CLZ
// Reversal: put x(31) at bit 0, x(0) at bit 31
def ctz32(x: UInt): UInt = {
  val rev = VecInit((31 to 0 by -1).map(i => x(i))).asUInt
  clz32(rev)
}

